import{_ as d,o,c as e,ae as c}from"./chunks/framework.DYeE-XvM.js";const p=JSON.parse('{"title":"匹配与开房","description":"","frontmatter":{},"headers":[],"relativePath":"rooms/matchmaking.md","filePath":"rooms/matchmaking.md","lastUpdated":null}'),a={name:"rooms/matchmaking.md"};function r(n,t,s,i,m,l){return o(),e("div",null,[...t[0]||(t[0]=[c('<h1 id="匹配与开房" tabindex="-1">匹配与开房 <a class="header-anchor" href="#匹配与开房" aria-label="Permalink to &quot;匹配与开房&quot;">​</a></h1><p><code>matchmaker_room</code>（<code>MatchmakerRoom</code>）是统一的 <strong>匹配入口</strong>：支持 <strong>主动匹配</strong>（Redis 排队凑齐人数后自动创建对局房）与 <strong>被动开房</strong>（房主创建房间码、成员加入、人满后由房主开始游戏）。对局创建后统一进入 <code>game_room</code>（<code>GameRoom</code>）。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>客户端使用 <code>joinOrCreate(&quot;matchmaker_room&quot;, options)</code>，options 与 <a href="/xcs.github.io/rooms/auth.html">鉴权</a> 一致：需携带有效 JWT（<code>token</code> 或 <code>accessToken</code>）。</li><li>服务端需 <strong>Redis 可用</strong>：排队、分布式锁、跨实例 <code>match:found</code> 通知均依赖 Redis；Redis 不可用时，同进程内仍可收到匹配结果，多实例场景下可能无法把结果投递到其它节点上的客户端。</li></ul><p>加入成功后，服务端会向该客户端发送 <code>mm:ready</code>，payload 含 <code>sessionId</code>。</p><h2 id="主动匹配-排队" tabindex="-1">主动匹配（排队） <a class="header-anchor" href="#主动匹配-排队" aria-label="Permalink to &quot;主动匹配（排队）&quot;">​</a></h2><p>客户端发送消息 <strong><code>match:find</code></strong>，body 类型要点（与源码 <code>MatchFindRequest</code> 一致）：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>modeId</code></td><td>玩法 / 模式标识，默认 <code>&quot;default&quot;</code>。</td></tr><tr><td><code>playersPerMatch</code></td><td>一局人数，服务端限制在 <strong>2～100</strong>。</td></tr><tr><td><code>region</code></td><td>可选，用于区分大区；未传时队列维度为 <code>global</code>。</td></tr><tr><td><code>skill</code></td><td>可选，预留段位或匹配分。</td></tr><tr><td><code>tags</code></td><td>可选，附加标签维度。</td></tr></tbody></table><p>服务端行为概要：</p><ol><li>将票据写入 Redis（队列 ZSET + 票据 KV），并返回 <strong><code>match:queued</code></strong>，含 <code>queueKey</code>。</li><li>使用短锁 + Lua 脚本从队列头部取出 <code>playersPerMatch</code> 个票据，组成一局 <code>matchId</code>，创建 <code>game_room</code>。</li><li>向相关客户端发送 <strong><code>match:found</code></strong>（见下文）；并通过 Redis 频道 <code>colyseus:mm:notify</code> 广播，便于 <strong>其它 Colyseus 进程</strong> 上的同一用户收到通知。</li></ol><p>取消排队：发送 <strong><code>match:cancel</code></strong>。服务端回复 <strong><code>match:cancelled</code></strong>，<code>ok</code> 表示是否成功从队列移除。</p><p>客户端断开连接时，若仍在排队，服务端会尝试自动取消该票据。</p><h2 id="被动开房-party-房间码" tabindex="-1">被动开房（Party / 房间码） <a class="header-anchor" href="#被动开房-party-房间码" aria-label="Permalink to &quot;被动开房（Party / 房间码）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>消息</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><code>party:create</code></td><td>客户端 → 服务端</td><td>body：<code>modeId</code>、<code>playersPerMatch</code>（2～100）、可选 <code>region</code>。</td></tr><tr><td><code>party:created</code></td><td>服务端 → 客户端</td><td><code>partyId</code>、<code>partyCode</code>（6 位易读码）、<code>modeId</code>、<code>playersPerMatch</code>、<code>leaderUserId</code>、<code>isLeader</code> 等。</td></tr><tr><td><code>party:join</code></td><td>客户端 → 服务端</td><td>body：<code>partyCode</code>（不区分大小写，服务端会 trim 并转大写）。</td></tr><tr><td><code>party:joined</code></td><td>服务端 → 客户端</td><td>当前人数 <code>count</code>、<code>playersPerMatch</code>、房主信息等。</td></tr><tr><td><code>party:update</code></td><td>服务端 → 客户端</td><td>成员变化时向在线成员广播人数与房主标识。</td></tr><tr><td><code>party:leave</code></td><td>客户端 → 服务端</td><td>离开队伍；若队伍为空则关闭 party。</td></tr><tr><td><code>party:left</code></td><td>服务端 → 客户端</td><td><code>ok</code>。</td></tr><tr><td><code>party:start</code></td><td>客户端 → 服务端</td><td><strong>仅房主</strong>可发；人数达到 <code>playersPerMatch</code> 后创建 <code>game_room</code> 并下发 <code>match:found</code>，随后关闭 party。</td></tr><tr><td><code>party:error</code></td><td>服务端 → 客户端</td><td>业务错误说明，如房间码无效、非房主开始、人数不足等。</td></tr></tbody></table><p>Party 数据在 Redis 中有 TTL（与实现一致，约 30 分钟量级），过期后房间码失效。</p><h2 id="match-found-与进入-game-room" tabindex="-1"><code>match:found</code> 与进入 <code>game_room</code> <a class="header-anchor" href="#match-found-与进入-game-room" aria-label="Permalink to &quot;`match:found` 与进入 `game_room`&quot;">​</a></h2><p>匹配成功或 party 开局后，客户端会收到 <strong><code>match:found</code></strong>，payload 核心字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>roomName</code></td><td>固定为 <code>game_room</code>。</td></tr><tr><td><code>roomId</code></td><td>Colyseus 房间 ID，用于 <code>joinById</code>。</td></tr><tr><td><code>matchId</code></td><td>对局 ID。</td></tr><tr><td><code>seatIndex</code></td><td>座位序号。</td></tr><tr><td><code>reconnectKey</code></td><td>断线重连校验用（见 <a href="/xcs.github.io/rooms/frame-sync-game-room.html">帧同步与游戏房</a>）。</td></tr><tr><td><code>joinOptions</code></td><td>建议原样作为 <strong>加入 <code>game_room</code> 的 options</strong>（含 <code>matchId</code>、<code>seatIndex</code>、<code>reconnectKey</code> 等）。</td></tr></tbody></table><p>典型客户端流程：</p><ol><li><code>joinOrCreate(&quot;matchmaker_room&quot;, { token })</code></li><li>发送 <code>match:find</code> 或 party 系列消息</li><li>监听 <code>match:found</code>，再 <code>client.joinById(payload.roomId, payload.joinOptions)</code>（或等价 API），并合并 JWT 字段若框架要求单独传 <code>token</code></li></ol><h2 id="实现参考-源码" tabindex="-1">实现参考（源码） <a class="header-anchor" href="#实现参考-源码" aria-label="Permalink to &quot;实现参考（源码）&quot;">​</a></h2><ul><li><code>src/rooms/MatchmakerRoom.ts</code>：消息注册、组局、<code>matchMaker.createRoom</code>、Redis 通知桥接。</li><li><code>src/services/matchmaking/MatchmakingService.ts</code>：队列 key、<code>enqueue</code> / <code>tryFormMatch</code>、party CRUD。</li><li><code>src/services/matchmaking/types.ts</code>：请求与 <code>MatchFoundPayload</code> 类型定义。</li></ul>',22)])])}const y=d(a,[["render",r]]);export{p as __pageData,y as default};
